private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
             // request calculation married(Y/N) nbEnfants salaireAnnuel
             // 4 fields are required
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // that's it - tax calculation
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
        }
</code></pre> <ul> <li>línea 1: el método recibe la matriz de campos de comando como tercer parámetro tax. Si está correctamente formulado, tiene la forma married tax nbEnfants salaireAnnuel. El resultado del método es la respuesta que se enviará al cliente.   </li> <li>línea 4: comprueba que el comando tiene 4 campos   </li> <li>línea 8: comprueba que married sea válido   </li> <li>línea 14: comprueba que el campo nbEnfants sea válido   </li> <li>línea 19: comprueba que «salaireAnnuel» sea válido   </li> <li>línea 25: tax se calcula utilizando CalculerImpot de la capa [metier]. Recuerde que esta capa está encapsulada en una DLL.   </li> <li>línea 26: si la capa [metier] ha devuelto un resultado, este se devuelve al cliente.   </li> <li>línea 28: si la capa [metier] ha lanzado una excepción, el mensaje de excepción se devuelve al cliente.   </li> </ul> <p></p>
